"""Ingress page listing the RTSP addresses generated by the add-on, with a thumbnail per channel."""
import json
import os
import subprocess
import threading
import time
import urllib.request
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer

INGRESS_PORT = 8099
# Home Assistant ingress always connects from this address; loopback is for local checks.
ALLOWED_PEERS = ('172.30.32.2', '127.0.0.1')
RTSP_CONTAINER_PORT = '8554/tcp'
DEFAULT_EXTERNAL_PORT = 18554
SUPERVISOR_INFO = 'http://supervisor/addons/self/info'
RTSP_LOCAL = 'rtsp://127.0.0.1:8554/'
SNAPSHOT_SECONDS = 20  # an on-demand channel needs a few seconds to open through P2P
SNAPSHOT_CACHE_SECONDS = 30
# Few at a time: every thumbnail opens a channel on the recorder through the P2P relay.
SNAPSHOT_SLOTS = threading.BoundedSemaphore(2)

PAGE = """<!doctype html>
<html lang="pt-BR"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1">
<title>Intelbras P2P</title>
<style>
:root { color-scheme: light dark; --bg: #fafafa; --card: #fff; --line: #d0d0d0; --text: #1c1c1c; --accent: #0288d1; }
@media (prefers-color-scheme: dark) {
  :root { --bg: #111; --card: #1c1c1c; --line: #3a3a3a; --text: #e6e6e6; --accent: #03a9f4; } }
body { margin: 0; padding: 16px; background: var(--bg); color: var(--text); font: 14px/1.4 system-ui, sans-serif; }
main { max-width: 860px; margin: 0 auto; }
h1 { font-size: 20px; margin: 0 0 4px; } h2 { font-size: 16px; margin: 0; }
p { margin: 4px 0 12px; opacity: .8; }
section { background: var(--card); border: 1px solid var(--line); border-radius: 10px; padding: 12px; margin-bottom: 12px; }
.fields { display: grid; grid-template-columns: repeat(auto-fit, minmax(170px, 1fr)); gap: 10px; }
label { display: block; font-size: 12px; opacity: .8; }
input, textarea { width: 100%; box-sizing: border-box; padding: 7px 8px; border: 1px solid var(--line); border-radius: 6px;
  background: var(--bg); color: var(--text); font: 13px ui-monospace, Consolas, monospace; }
textarea { resize: vertical; white-space: pre; }
.head, .row { display: flex; gap: 8px; align-items: center; }
.head { justify-content: space-between; margin-bottom: 8px; }
.row { margin-top: 6px; } .row input { flex: 1; min-width: 0; }
.chan { display: flex; gap: 10px; align-items: center; padding-top: 10px; margin-top: 10px; border-top: 1px solid var(--line); }
.chan .urls { flex: 1; min-width: 0; } .chan .row:first-child { margin-top: 0; }
.thumb { width: 160px; height: 90px; flex: none; border-radius: 6px; background: #000; color: #999; cursor: pointer;
  display: flex; align-items: center; justify-content: center; font-size: 12px; overflow: hidden; }
.thumb img { width: 100%; height: 100%; object-fit: cover; }
@media (max-width: 560px) { .chan { flex-direction: column; align-items: stretch; }
  .thumb { width: 100%; height: auto; aspect-ratio: 16/9; } }
button { padding: 7px 12px; border: 0; border-radius: 6px; background: var(--accent); color: #fff; cursor: pointer;
  font: inherit; white-space: nowrap; }
</style></head><body><main>
<h1>Endereços RTSP</h1>
<p>Confira o endereço do Home Assistant e digite a senha RTSP para montar os endereços completos.
A senha fica apenas nesta página e não é enviada a lugar nenhum. Clique em uma miniatura para atualizá-la.</p>
<section class="fields">
<div><label for="host">Endereço do Home Assistant</label><input id="host"></div>
<div><label for="port">Porta RTSP</label><input id="port" inputmode="numeric"></div>
<div><label for="user">Usuário RTSP</label><input id="user"></div>
<div><label for="pass">Senha RTSP</label><input id="pass" type="password" autocomplete="off" placeholder="SENHA"></div>
</section>
<section>
<div class="head"><h2>Configuração para o Frigate</h2><button id="copy-yaml">Copiar YAML</button></div>
<p>Cole em <code>config.yml</code> do Frigate. Cada câmera usa o stream secundário para detecção e o principal
para gravação; apague as câmeras que não quiser.</p>
<textarea id="yaml" readonly rows="10" spellcheck="false"></textarea>
</section>
<div id="list"></div>
</main><script>
const data = __DATA__;
const $ = id => document.getElementById(id);
$('host').value = location.hostname || 'IP_DO_HOME_ASSISTANT';
$('port').value = data.port;
$('user').value = data.user;
function url(name) {
  const pass = $('pass').value ? encodeURIComponent($('pass').value) : 'SENHA';
  return 'rtsp://' + encodeURIComponent($('user').value) + ':' + pass + '@' + $('host').value.trim() + ':' +
    $('port').value.trim() + '/' + name;
}
function copy(text, button) {
  const done = () => { const old = button.textContent; button.textContent = 'Copiado';
    setTimeout(() => { button.textContent = old; }, 1200); };
  const fallback = () => {  // navigator.clipboard is missing when Home Assistant is opened over plain http
    const area = document.createElement('textarea');
    area.value = text; document.body.appendChild(area); area.select();
    try { if (document.execCommand('copy')) done(); } finally { area.remove(); }
  };
  if (navigator.clipboard && window.isSecureContext) navigator.clipboard.writeText(text).then(done, fallback);
  else fallback();
}
const inputs = [];
function thumbnail(stream) {
  const box = document.createElement('div'); box.className = 'thumb'; box.title = stream;
  const load = () => {
    const img = new Image(); img.alt = stream; img.loading = 'lazy';
    img.onerror = () => { box.textContent = 'Sem imagem'; };
    img.src = 'snapshot/' + stream + '?t=' + Date.now();  // relative: ingress serves the page under a prefix
    box.replaceChildren(img);
  };
  box.onclick = load; load();
  return box;
}
for (const names of data.recorders) {
  const section = document.createElement('section');
  const head = document.createElement('div'); head.className = 'head';
  const title = document.createElement('h2'); title.textContent = names[0].replace(/_ch[0-9]+$/, '');
  const all = document.createElement('button'); all.textContent = 'Copiar todos';
  all.onclick = () => copy(names.map(url).join('\\n'), all);
  head.append(title, all); section.append(head);
  for (const name of names) {
    if (name.endsWith('_sub')) continue;
    const chan = document.createElement('div'); chan.className = 'chan';
    const lighter = names.includes(name + '_sub') ? name + '_sub' : name;
    const urls = document.createElement('div'); urls.className = 'urls';
    for (const stream of new Set([name, lighter])) {
      const row = document.createElement('div'); row.className = 'row';
      const input = document.createElement('input'); input.readOnly = true; input.dataset.name = stream;
      input.onfocus = () => input.select();
      const button = document.createElement('button'); button.textContent = 'Copiar';
      button.onclick = () => copy(input.value, button);
      row.append(input, button); urls.append(row); inputs.push(input);
    }
    chan.append(thumbnail(lighter), urls); section.append(chan);
  }
  $('list').append(section);
}
function frigate() {
  const lines = ['cameras:'];
  for (const names of data.recorders) for (const name of names) {
    if (name.endsWith('_sub')) continue;
    const detect = names.includes(name + '_sub') ? name + '_sub' : name;
    lines.push('  ' + name + ':', '    ffmpeg:', '      inputs:');
    if (detect === name) lines.push('        - path: "' + url(name) + '"', '          roles: [detect, record]');
    else lines.push('        - path: "' + url(detect) + '"', '          roles: [detect]',
                    '        - path: "' + url(name) + '"', '          roles: [record]');
  }
  return lines.join('\\n') + '\\n';
}
$('copy-yaml').onclick = () => copy($('yaml').value, $('copy-yaml'));
function refresh() {
  for (const input of inputs) input.value = url(input.dataset.name);
  $('yaml').value = frigate();
}
for (const id of ['host', 'port', 'user', 'pass']) $(id).addEventListener('input', refresh);
refresh();
</script></body></html>
"""


def page(config, port):
    """The HTML page. Carries the RTSP user and stream names only: no passwords and no serials."""
    data = {'user': config['output_auth']['username'], 'port': port,
            'recorders': [[stream['name'] for stream in device['streams']] for device in config['devices']]}
    # "<" is escaped so a user name can never close the script element.
    return PAGE.replace('__DATA__', json.dumps(data).replace('<', '\\u003c')).encode()


def snapshot(name, cache={}, lock=threading.Lock()):
    """One small JPEG frame of a stream read from the local mediamtx, or None when no video arrives."""
    with lock:
        saved = cache.get(name)
    if saved and time.monotonic() - saved[0] < SNAPSHOT_CACHE_SECONDS:
        return saved[1]
    with SNAPSHOT_SLOTS:
        try:
            image = subprocess.run(
                ['ffmpeg', '-nostdin', '-loglevel', 'quiet', '-rtsp_transport', 'tcp', '-i', RTSP_LOCAL + name,
                 '-frames:v', '1', '-vf', 'scale=320:-2', '-q:v', '6', '-f', 'image2pipe', '-vcodec', 'mjpeg', '-'],
                stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, timeout=SNAPSHOT_SECONDS).stdout
        except (OSError, subprocess.SubprocessError):
            return None
    if not image.startswith(b'\xff\xd8'):
        return None
    with lock:
        cache[name] = (time.monotonic(), image)
    return image


def external_port():
    """Host port mapped to RTSP in the add-on Network section, or the default when it cannot be read."""
    try:
        request = urllib.request.Request(
            SUPERVISOR_INFO, headers={'Authorization': 'Bearer ' + os.environ['SUPERVISOR_TOKEN']})
        with urllib.request.urlopen(request, timeout=3) as response:
            port = json.load(response)['data']['network'][RTSP_CONTAINER_PORT]
        return port if type(port) is int else DEFAULT_EXTERNAL_PORT
    except (OSError, ValueError, KeyError, TypeError):
        return DEFAULT_EXTERNAL_PORT


def serve(config, port=INGRESS_PORT):
    """Serve the page from a daemon thread, so it never delays or changes the bridge shutdown."""
    body = []
    names = {stream['name'] for device in config['devices'] for stream in device['streams']}

    class Handler(BaseHTTPRequestHandler):
        def do_GET(self):
            if self.client_address[0] not in ALLOWED_PEERS:
                self.send_error(403)
                return
            path = self.path.split('?', 1)[0]
            if '/snapshot/' in path:
                name = path.rsplit('/', 1)[1]
                if name not in names:  # only configured streams ever reach the ffmpeg command line
                    self.send_error(404)
                    return
                content, kind = snapshot(name), 'image/jpeg'
                if content is None:
                    self.send_error(503)
                    return
            else:
                if not body:
                    body.append(page(config, external_port()))
                content, kind = body[0], 'text/html; charset=utf-8'
            self.send_response(200)
            self.send_header('Content-Type', kind)
            self.send_header('Content-Length', str(len(content)))
            self.send_header('Cache-Control', 'no-store')
            self.end_headers()
            self.wfile.write(content)

        def log_message(self, *_):
            pass

    server = ThreadingHTTPServer(('', port), Handler)
    server.daemon_threads = True
    threading.Thread(target=server.serve_forever, daemon=True).start()
    return server
